#include "NoiseLayer.h"
namespace cymbalforge {
void NoiseLayer::prepare(double sampleRate) { contactDecay = std::exp(-1.0f / float(sampleRate * 0.018)); washDecay = std::exp(-1.0f / float(sampleRate * 0.65)); }
void NoiseLayer::strike(float velocity, float newBrightness, float amount, float newTone, float shimmer, int model, int exciter) { brightness = newBrightness; tone = newTone; const float washByModel[] { 1.0f, 0.55f, 1.55f }; const float contactByExciter[] { 1.0f, .48f, .24f, .10f }; const float washByExciter[] { .75f, .62f, 1.2f, 1.55f }; const auto style=juce::jlimit(0,3,exciter); washColour = washByModel[juce::jlimit(0, 2, model)]; contactEnvelope = juce::jmax(contactEnvelope, velocity * amount * contactByExciter[style] * (0.3f + 0.7f * newBrightness)); washEnvelope = juce::jmax(washEnvelope, velocity * amount * washColour * washByExciter[style] * (0.08f + shimmer * 0.42f)); }
std::array<float, 2> NoiseLayer::process() { auto white = random.nextFloat() * 2.0f - 1.0f; slow += 0.012f * (white - slow); medium += (0.07f + brightness * 0.12f) * (white - medium); auto metallicBand = medium - slow; auto air = white - medium; const auto body = slow; const auto colour = (tone < .5f) ? juce::jmap(tone, 0.0f, .5f, body, metallicBand) : juce::jmap(tone, .5f, 1.0f, metallicBand, air); auto mono = colour * contactEnvelope + metallicBand * washEnvelope; contactEnvelope *= contactDecay; washEnvelope *= washDecay; auto side = (random.nextFloat() * 2.0f - 1.0f) * washEnvelope * 0.10f * washColour; return { mono + side, mono - side }; }
}
